composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      DB_HOST: "{{serviceName}}-mariadb"
      DB_DATABASE: monica
      DB_USERNAME: monica
      APP_KEY: {{env.APP_KEY}}
      DB_PASSWORD: {{env.DB_PASSWORD}}
      APP_URL: {{env.APP_URL}}
    volumes:
      - {{appDataPath}}/data:/var/www/html/storage
    depends_on:
      - {{serviceName}}-mariadb
  {{serviceName}}-mariadb:
    image: mariadb:11
    container_name: {{serviceName}}-mariadb
    restart: unless-stopped
    environment:
      MYSQL_DATABASE: monica
      MYSQL_USER: monica
      MYSQL_PASSWORD: {{env.DB_PASSWORD}}
      MYSQL_ROOT_PASSWORD: {{env.DB_PASSWORD}}
    volumes:
      - {{appDataPath}}/mariadb:/var/lib/mysql
